package com.match.account.web;
import com.match.account.service.AccountTemplateService; import com.match.security.AdminGuard; import com.match.entity.User; import com.match.util.result.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/admin/account-templates") public class AccountTemplateController { private final AccountTemplateService service; private final AdminGuard guard; public AccountTemplateController(AccountTemplateService service,AdminGuard guard){this.service=service;this.guard=guard;} @GetMapping public ResponseResult<Object> list(){guard.requireAdmin();return Response.makeOKRsp(service.list());} @PostMapping public ResponseResult<Object> save(@RequestBody Map<String,Object> body){User actor=guard.requireAdmin();Map<String,String> fields=new LinkedHashMap<>();Object raw=body==null?null:body.get("customFields");if(raw instanceof Map)for(Map.Entry<?,?> e:((Map<?,?>)raw).entrySet())fields.put(String.valueOf(e.getKey()),String.valueOf(e.getValue()));return Response.makeOKRsp(service.save(body==null?null:String.valueOf(body.get("templateName")),fields,Boolean.TRUE.equals(body==null?null:body.get("requireProfile")),actor.getUserId()));} }
